function quotaForPreview(){if(sources.Magpie){const n=currentMagpie?.find(x=>x.provider==='codex')?.windows?.find(x=>x.name==='7 days')?.remaining;return typeof n==='number'&&Number.isFinite(n)?{primary:Math.max(0,Math.min(100,Math.round(n))),weekly:Math.max(0,Math.min(100,Math.round(n)))}:null}if(sources.Claude&&!sources.Codex&&currentClaude.status==='fresh')return {primary:currentClaude.primary,weekly:currentClaude.weekly};return sources.Codex&&!sources.Claude?currentQuota:null}
function updateQuotaStatus(){const available=quotaForPreview();$('#quotaStatus').dataset.base=sources.Magpie?(currentMagpie?'四格：Magpie · 水位与外环：'+(currentQuota?'Codex 缓存':'暂不可用'):'Magpie 额度暂不可用'):'Agent 来源 · 水位与环：'+(available?(sources.Claude?'Claude 状态栏缓存':'Codex 上次保存的额度'):(sources.Claude&&currentClaude.status==='stale'?'Claude 缓存已过期':'当前组合额度未取得'));$('#quotaStatus').textContent=$('#quotaStatus').dataset.base}
