function mix(a,b,t){let A=parseInt(a.slice(1),16),B=parseInt(b.slice(1),16);return '#'+[16,8,0].map(i=>Math.round(((A>>i)&255)*(1-t)+((B>>i)&255)*t).toString(16).padStart(2,'0')).join('').toUpperCase()}
