function material(hex,opts={}){return new THREE.MeshStandardMaterial({color:hex,roughness:.38,metalness:.12,...opts})}
function outlineFor(id,geometry){
 if(id==='base'){const mesh=new THREE.Mesh(geometry.clone(),new THREE.MeshBasicMaterial({color:0xFFCD42,side:THREE.BackSide,depthTest:true,depthWrite:false}));mesh.scale.setScalar(1.035);return mesh}
 geometry.computeBoundingBox();const box=geometry.boundingBox,depth=box.max.z+.035;let points=[];
 if(geometry.type==='ExtrudeGeometry'&&!['ring','track','focus'].includes(id)){const raw=Array.isArray(geometry.parameters.shapes)?geometry.parameters.shapes[0]:geometry.parameters.shapes;if(raw)points=raw.getPoints(48).map(p=>new THREE.Vector3(p.x,p.y,depth))}
 if(points.length<4){const center=box.getCenter(new THREE.Vector3()),radiusX=(box.max.x-box.min.x)/2+.025,radiusY=(box.max.y-box.min.y)/2+.025;for(let i=0;i<80;i++){const angle=i*Math.PI*2/80;points.push(new THREE.Vector3(center.x+radiusX*Math.cos(angle),center.y+radiusY*Math.sin(angle),depth))}}
 const curve=new THREE.CatmullRomCurve3(points,true);return new THREE.Mesh(new THREE.TubeGeometry(curve,Math.max(64,points.length*2),.018,6,true),new THREE.MeshBasicMaterial({color:0xFFD04A,depthTest:false,depthWrite:false}))
}
function replaceOutline(part){const old=part.userData.outline;part.remove(old);old.geometry.dispose();old.material.dispose();const next=outlineFor(part.userData.id,part.userData.mesh.geometry);next.visible=false;next.renderOrder=100;part.add(next);part.userData.outline=next}

function addPart(id,geometry,home,exploded,options={}){const group=new THREE.Group();const mesh=new THREE.Mesh(geometry,material(state.colors[id]||'#ffffff',options.material));group.add(mesh);const outline=outlineFor(id,geometry);outline.visible=false;outline.renderOrder=100;group.add(outline);group.position.set(...home);group.userData={id,outline,home:new THREE.Vector3(...home),exploded:explosionTarget(id,home),mesh};mesh.userData.part=id;root.add(group);pickables.push(mesh);parts.set(id,group);return group}
function label(text,color='#FFFFFF',size=42){const c=document.createElement('canvas');c.width=512;c.height=128;const x=c.getContext('2d');x.clearRect(0,0,512,128);x.textAlign='center';x.textBaseline='middle';x.font=`700 ${size}px "Avenir Next",sans-serif`;x.fillStyle=color;x.fillText(text,256,65);const texture=new THREE.CanvasTexture(c);texture.colorSpace=THREE.SRGBColorSpace;const s=new THREE.Sprite(new THREE.SpriteMaterial({map:texture,transparent:true,depthTest:false}));s.scale.set(2.35,.59,1);return s}
function addLabel(group,text,color,size,scale=1){const s=label(text,color,size);s.position.z=.18;s.scale.multiplyScalar(scale);group.add(s);s.userData.part=group.userData.id;pickables.push(s)}
function rounded(w,h,r=.13,depth=.12){const x=-w/2,y=-h/2,s=new THREE.Shape();s.moveTo(x+r,y);s.lineTo(x+w-r,y);s.quadraticCurveTo(x+w,y,x+w,y+r);s.lineTo(x+w,y+h-r);s.quadraticCurveTo(x+w,y+h,x+w-r,y+h);s.lineTo(x+r,y+h);s.quadraticCurveTo(x,y+h,x,y+h-r);s.lineTo(x,y+r);s.quadraticCurveTo(x,y,x+r,y);return new THREE.ExtrudeGeometry(s,{depth,bevelEnabled:true,bevelThickness:.025,bevelSize:.025,bevelSegments:3})}
function disposeObject(o){o.traverse(n=>{if(n.geometry)n.geometry.dispose();if(n.material){const arr=Array.isArray(n.material)?n.material:[n.material];for(const m of arr){if(m.map)m.map.dispose();m.dispose()}}})}
function clearModel(){for(const c of [...root.children]){root.remove(c);disposeObject(c)}parts=new Map();pickables=[]}
function cylinder(radius,thickness){const g=new THREE.CylinderGeometry(radius,radius,thickness,64);g.rotateX(Math.PI/2);return g}
function liquidGeometry(level=62){const r=1.19, surface=Math.max(-r+.001,Math.min(r-.001,-r+2*r*level/100)),angle=Math.asin(surface/r),s=new THREE.Shape();s.moveTo(r*Math.cos(angle),r*Math.sin(angle));s.absarc(0,0,r,angle,Math.PI-angle,true);s.closePath();const geometry=new THREE.ExtrudeGeometry(s,{depth:.09,bevelEnabled:true,bevelThickness:.015,bevelSize:.015,bevelSegments:2,curveSegments:64});geometry.userData.surfaceY=surface;return geometry}
function ringGeometry(outer,inner,depth=.12){const s=new THREE.Shape();s.absarc(0,0,outer,0,Math.PI*2,false);const h=new THREE.Path();h.absarc(0,0,inner,0,Math.PI*2,true);s.holes.push(h);return new THREE.ExtrudeGeometry(s,{depth,bevelEnabled:true,bevelThickness:.018,bevelSize:.018,bevelSegments:2,curveSegments:64})}
