 const run=addPart('running',cylinder(.09,.08),[-1.54,-.37,.38],[2.2,.15,1]);const pend=addPart('pending',cylinder(.09,.08),[-1.25,-.37,.38],[-2.2,.15,1]);void run;void pend
 const scenario=currentScenario();const providerIds=scenario.magpie?['codex','grok','cursor','cursorOther']:['codex','claude','cursor'].filter(id=>scenario.providers.some(p=>p.toLowerCase()===id));providerIds.forEach((id,index)=>{const spacing=3.3/Math.max(providerIds.length,1),x=-1.65+spacing*(index+.5);const part=addPart(id,rounded(Math.min(.78,spacing-.08),.32,.07,.06),[x,.18,.33],[-1.5+index*1.05,-.65,1.2]);const labels={codex:'C',grok:'G',cursor:'U',cursorOther:'O',claude:'L'};const gridIndex={codex:0,grok:1,cursor:2,cursorOther:3};const value=scenario.magpie?(currentGrid?.[gridIndex[id]]?.[1]||'—'):id==='codex'&&currentQuota?.primary!=null?`${currentQuota.primary}%`:id==='claude'&&currentClaude.status==='fresh'?`${currentClaude.primary}%`:'—';addLabel(part,`${labels[id]} ${value}`,'#FFFFFF',49,.55)})
