function activeDefs(){const scenario=currentScenario();return definitions[state.model].filter(([id])=>{if(state.model==='ball'&&['input','active','unread'].includes(id))return taskCounts()===null||taskCounts()[id]>0;if(['codex','claude','cursor','cursorOther','grok'].includes(id)){if(scenario.magpie)return ['codex','grok','cursor','cursorOther'].includes(id);return id!=='grok'&&id!=='cursorOther'&&scenario.providers.some(p=>p.toLowerCase()===id)}return true})}
