setInterval(async()=>{if(!sources.Claude||sources.Magpie)return;try{const r=await fetch('/api/claude-quota',{cache:'no-store'});if(!r.ok)return;const next=await r.json();if(JSON.stringify(next)===JSON.stringify(currentClaude))return;currentClaude=next;const selected=state.selected,expanded=[...state.expanded];updateQuotaStatus();rebuild();for(const id of expanded)if(parts.has(id))state.expanded.add(id);if(selected&&parts.has(selected))state.selected=selected;refresh()}catch{}},30000)

