let runtimeFingerprint='';async function pollRuntimeTasks(){if(window.eypcPlatform?.companionKernel)return;try{const r=await fetch('/api/runtime-tasks',{cache:'no-store'});if(!r.ok)return;const next=await r.json(),fingerprint=JSON.stringify(next);if(fingerprint===runtimeFingerprint)return;runtimeFingerprint=fingerprint;taskProjection=next;const selected=state.selected,expanded=[...state.expanded];rebuild();for(const id of expanded)if(parts.has(id))state.expanded.add(id);if(selected&&parts.has(selected))state.selected=selected;refresh()}catch{if(taskProjection){taskProjection=null;runtimeFingerprint='';rebuild()}}}pollRuntimeTasks();setInterval(pollRuntimeTasks,5000)
